// game initialization
tiles.setCurrentTilemap(tilemap`tilemap`)

let upsideDown = false
let spriteImage = [assets.image`spriteImage`, assets.image`upsideDownImage`]
let spriteAcceleration = 200

let mySprite = sprites.create(spriteImage[0], SpriteKind.Player)
scene.cameraFollowSprite(mySprite)
controller.moveSprite(mySprite, 100, 0)
mySprite.setStayInScreen(true)

function setStars() {
    sprites.destroyAllSpritesOfKind(SpriteKind.Player)
    for (let index = 0; index < 10; index++) {
        let star = sprites.create(assets.image`star`, SpriteKind.Food)
        tiles.placeOnRandomTile(star, assets.tile`cloudTile`)
        animation.runMovementAnimation(star, animation.animationPresets(animation.bobbing), 2000, true)
    }
}

function startGame() {
    upsideDown = false
    scene.setBackgroundColor(9)
    mySprite.setImage(spriteImage[0])
    mySprite.ay = spriteAcceleration
    tiles.placeOnTile(mySprite, tiles.getTileLocation(5, 28))
    setStars()
}

// game start
startGame()

// game events
controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (!upsideDown) {
        upsideDown = true
        mySprite.setImage(spriteImage[1])
        scene.setBackgroundColor(8)
    } else {
        upsideDown = false
        mySprite.setImage(spriteImage[0])
        scene.setBackgroundColor(9)
    }
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Food, function (sprite, otherSprite) {
    sprites.destroy(otherSprite)
})

scene.onHitWall(SpriteKind.Player, function (sprite: Sprite, location: tiles.Location) {
    if (tiles.tileAtLocationEquals(location, assets.tile`spikeTileUp`)) {
        startGame()
    }
})

